      "content": "{\n  \"name\": \"deepseek-harness-wallet\",\n  \"description\": \"Local-first DeepSeek Harness control center for balance monitoring, usage accounting, time-aware custom third-party API pricing, a 365-day local token ledger, Z.ai Coding Plan quotas, official pricing sync, encrypted multi-account switching, reminders, recharge, and host-gated session controls.\",\n  \"version\": \"0.3.13\",\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"exports\": {\n    \".\": \"./index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"CHANGELOG.md\",\n    \"index.js\",\n    \"lib/client.js\",\n    \"lib/plans.js\",\n    \"cordis.patch.yml\",\n    \"integrations/dsh-session-delete/**\"\n  ],\n  \"license\": \"MIT\",\n  \"scripts\": {\n    \"build:client\": \"node scripts/build-client.mjs\",\n    \"check:client\": \"node scripts/build-client.mjs --check\",\n    \"check:store-size\": \"node scripts/check-review-surface.mjs\",\n    \"check:syntax\": \"node --check index.js && node --check lib/client.js && node --check lib/plans.js\",\n    \"check:pack\": \"node scripts/verify-pack.mjs\",\n    \"test\": \"node --test\"\n  },\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"balance-monitor\",\n    \"recharge\",\n    \"token-tracking\",\n    \"cost-tracking\",\n    \"wallet\",\n    \"multi-account\",\n    \"account-switching\",\n    \"coding-plan\",\n    \"quota-monitoring\",\n    \"llm\",\n    \"agentic-ai\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/feibi-mochi/deepseek-harness-control-center.git\"\n  },\n  \"homepage\": \"https://github.com/feibi-mochi/deepseek-harness-control-center#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/feibi-mochi/deepseek-harness-control-center/issues\"\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\"\n  },\n  \"dsh\": {\n    \"compatibility\": {\n      \"dsh\": \">=0.1.2-alpha.3 <0.1.3 || =0.1.5-alpha.1\",\n      \"node\": \"^22.19.0 || >=24.0.0\",\n      \"systems\": [\"windows\", \"linux\", \"macos\"],\n      \"profiles\": [\"web\"],\n      \"dshReleases\": {\n        \"0.1.2-alpha.3\": \"compatible\",\n        \"0.1.2-alpha.4\": \"compatible\",\n        \"0.1.2-alpha.5\": \"compatible\",\n        \"0.1.2-rc.1\": \"compatible\",\n        \"0.1.5-alpha.1\": \"compatible\"\n      }\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-slots\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-model-selection\"\n      ]\n    }\n  },\n  \"devDependencies\": {\n    \"esbuild\": \"0.25.9\"\n  }\n}\n"
